const DriverLiveMapLazy = React.lazy(() => import("./seller/DriverLiveMap.jsx"));
function DriverLiveMap(props) {
  // Loading placeholder for the live map — stays a dark neutral fill in both themes so there's
  // no light flash before the dark map tiles mount (the map itself is deliberately dark-only,
  // same reasoning as Quotes.jsx's provider map).
  return (
    <React.Suspense fallback={<div style={{ height: props.fill ? "100%" : (props.height || 240), background: "rgba(255,255,255,0.04)" }} />}>
      <DriverLiveMapLazy {...props} />
    </React.Suspense>
  );
}

