function sdCommon(key, opts) {
  return i18n.t(`sellerDash.common.${key}`, opts);
}
function translateSellerStatus(status) {
  if (status == null || status === "") return "—";
  const norm = String(status).toLowerCase().replace(/_/g, " ").trim();
  const key = {
    pending: "statusPending",
    processing: "statusProcessing",
    preparing: "statusPreparing",
    confirmed: "statusConfirmed",
    shipped: "statusShipped",
    fulfilled: "statusFulfilled",
    delivered: "statusDelivered",
    completed: "statusCompleted",
    rejected: "statusRejected",
    cancelled: "statusCancelled",
    canceled: "statusCancelled",
    ready: "readyForPickup",
    "ready for pickup": "readyForPickup",
    "picked up": "statusPickedUp",
    accepted: "statusAccepted",
    rescheduled: "statusRescheduled",
    inactive: "statusInactive",
    available: "statusAvailable",
    sold: "statusSold",
    leased: "statusLeased",
    "under offer": "statusUnderOffer",
    active: "statusActive",
    unavailable: "statusUnavailable",
    paused: "statusPaused",
    declined: "statusDeclined",
    ongoing: "statusOngoing",
    requested: "statusRequested",
    "awaiting host": "statusAwaitingHost",
    "no show": "statusNoShow",
    "in progress": "statusInProgress",
  }[norm];
  return key ? sdCommon(key) : status;
}

function grocerySubstitutionStatusLabel(substitution) {
  const raw = substitution?.response || substitution?.status || "pending";
  const norm = String(raw).toLowerCase().replace(/_/g, " ").trim();
  const key = {
    pending: "statusPending",
    "pending customer": "pendingCustomerApproval",
    approved: "statusApproved",
    rejected: "statusRejected",
  }[norm];
  return key ? sdCommon(key, { defaultValue: norm === "pending customer" ? "Waiting for customer" : raw }) : raw;
}

/** Map API food_order.order_status → restaurant Orders-tab labels. */
function normalizeFoodOrderStatus(raw) {
  const s = String(raw || "pending").toLowerCase().replace(/\s+/g, "_");
  if (s === "pending") return "Pending";
  if (s === "confirmed") return "Confirmed";
  if (s === "dispatched") return "Dispatched";
  if (s === "preparing") return "Preparing";
  if (s === "ready_for_pickup" || s === "ready") return "Ready for Pickup";
  if (s === "picked_up" || s === "pickedup") return "Picked Up";
  if (s === "delivered" || s === "completed") return "Delivered";
  if (s === "cancelled" || s === "canceled" || s === "rejected") return "Rejected";
  if (
    raw === "Pending" ||
    raw === "Confirmed" ||
    raw === "Dispatched" ||
    raw === "Preparing" ||
    raw === "Ready for Pickup" ||
    raw === "Picked Up" ||
    raw === "Delivered" ||
    raw === "Rejected"
  ) {
    return raw;
  }
  return raw || "Pending";
}

