                                background: deliveryProofMode === mode ? "rgba(34,197,94,0.16)" : "rgba(255,255,255,0.04)",
                                color: deliveryProofMode === mode ? "#bbf7d0" : "rgba(255,255,255,0.72)",
                                fontSize: 12,
                                fontWeight: 700,
                                fontFamily: "'DM Sans', sans-serif",
                                cursor: "pointer",
                                textTransform: "capitalize",
