// Map a food-dashboard backNav to its canonical vendor_type NAME. The user-facing feeds and
// the create/lookup paths all key off the NAME (not a fragile hard-coded id), so this is the
// single source of truth shared by registration (create) and the status check (lookup).
const FOOD_VENDOR_TYPE_BY_NAV = {
  groceries: "Grocery",
  liquor: "Liquor",
  pharmacy: "Pharmacy",
  catering: "Catering",
  floral: "Floral",
  flowers: "Floral",
};

// #198 profile-bleed: each food-family dashboard owns an isolated vertical_profile
// (identity no longer shares the per-user store_profile). reservations = same food vendor.
const FOOD_VERTICAL_SLUG_BY_NAV = {
  groceries: "grocery",
  liquor: "liquor",
  pharmacy: "pharmacy",
  catering: "catering",
  floral: "floral",
  flowers: "floral",
  food: "food",
  reservations: "food",
};
const foodVerticalSlug = (backNav) => FOOD_VERTICAL_SLUG_BY_NAV[backNav] || "food";

function unwrapFoodVendor(data) {
  return data?.data ?? data?.food_vendor ?? data ?? {};
}

function foodVendorRowId(vendor) {
  return vendor?.vendor_id ?? vendor?.food_vendor_id ?? vendor?.id ?? null;
}

/** Format booking engine HH:MM (or pass-through) for host reservation cards. */
function formatReservationTimeLabel(time) {
  if (!time) return "";
  const raw = String(time).trim();
  if (/am|pm/i.test(raw)) return raw;
  const m = /^(\d{1,2}):(\d{2})$/.exec(raw);
  if (!m) return raw;
  let h = parseInt(m[1], 10);
  const min = m[2];
  const ap = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${min} ${ap}`;
}

function reservationDateValue(dateStr) {
  if (!dateStr) return null;
  const d = new Date(`${String(dateStr).slice(0, 10)}T12:00:00`);
  return Number.isNaN(d.getTime()) ? null : d;
}

function isReservationUpcoming(r) {
  const d = reservationDateValue(r.date);
  if (!d) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  d.setHours(0, 0, 0, 0);
  const terminal = r.status === "cancelled" || r.status === "declined" || r.status === "completed";
  return !terminal && d >= today;
}

/**
 * Guest display name from booking-engine payloads.
 * Prefer joined `guest` from GET /booking/bookings (BE guest/host relations),
 * then flat/socket fields, then social-profile hydration as last resort.
 */
function bookingGuestNameFromPayload(b) {
  const candidates = [
    b?.guest?.name,
    b?.guest?.username,
    b?.guest?.display_name,
    b?.guest?.user?.name,
    b?.guest_name,
    b?.user_name,
    b?.customer_name,
  ];
  for (const v of candidates) {
    if (typeof v === "string" && v.trim()) return v.trim();
  }
  return null;
}

function bookingGuestIdFromPayload(b) {
  const raw = b?.guest_id ?? b?.guestId ?? b?.guest?.user_id ?? b?.guest?.id;
  if (raw == null || raw === "") return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

function reservationGuestLabel(name, guestId) {
  if (name) return name;
  if (guestId != null) return `Guest #${guestId}`;
  return sdCommon("customer");
}

/**
 * When the bookings list has guest_id but no joined guest name (BE #923 pending),
 * hydrate display names from social profiles — one request per unique guest.
 */
async function hydrateReservationGuestNames(rows) {
  const needIds = [...new Set(
    (rows || [])
      .filter((r) => !r.customer_name && r.guest_id != null)
      .map((r) => r.guest_id),
  )];
  if (!needIds.length) return rows;
  const entries = await Promise.all(
    needIds.map(async (id) => {
      try {
        const d = await getProfileByUserId(id);
        const p = d?.data ?? d;
        const name = p?.display_name ?? p?.name ?? (p?.handle ? `@${p.handle}` : null);
        return [id, typeof name === "string" && name.trim() ? name.trim() : null];
      } catch {
        return [id, null];
      }
    }),
  );
  const byId = Object.fromEntries(entries);
  return rows.map((r) => {
    if (r.customer_name || r.guest_id == null) return r;
    const name = byId[r.guest_id];
    if (!name) return r;
    return { ...r, customer_name: name, user: { name } };
  });
}

