  React.useEffect(() => {
    if (isDoctorsPortal) return undefined;
    const user = getUser();
    if (!user?.id) return;
    const s = connectSocket();
    const eventName = useLessonOrders
      ? `lesson-request-${user.id}`
      : useAppointments
        ? `appointment-created-${user.id}`
        : `work-request-${user.id}`;
    const handler = async (data) => {
      const id = data.order_id ?? data.id;
      let extra = {};
      if (!useLessonOrders && !useAppointments && id) {
        try {
          const full = await getServiceOrder(Number(id));
          extra = {
            client: full.user?.name ?? extra.client,
            service: full.service_type?.name ?? extra.service,
            amount: full.total
              ? `${$m((parseFloat(full.total) * 0.79))}`
              : sdCommon("quoted"),
            deliver_lat: full.deliver_lat,
            deliver_long: full.deliver_long,
            location:
              full.deliver_lat && full.deliver_long
                ? await reverseGeocode(full.deliver_lat, full.deliver_long)
                : (data.location ?? sdCommon("onSite")),
            note: full.note ?? full.description ?? "",
          };
        } catch { /* enrich optional */ }
      }
      setWorkRequests((prev) => {
        if (prev.some((r) => r.id === id)) return prev;
        return [
          {
            id,
            client:
              data.client_name ??
              data.student_name ??
              data.patient_name ??
              extra.client ??
              "Client",
            service:
              data.service_name ??
              data.lesson_title ??
              data.appointment_type ??
              extra.service ??
              config.serviceLabel ??
              "Service",
            location: extra.location ?? data.location ?? sdCommon("online"),
            amount:
              extra.amount ??
              (data.amount
                ? `${$m((parseFloat(data.amount) * 0.79))}`
                : sdCommon("quoted")),
            scheduled: data.scheduled_at ?? data.appointment_date ?? "ASAP",
            deliver_lat: extra.deliver_lat,
            deliver_long: extra.deliver_long,
            note: data.note ?? data.description ?? extra.note ?? "",
            photos: data.photos ?? data.images ?? [],
          },
          ...prev,
        ];
      });
    };
    s.on(eventName, handler);
    if (useLessonOrders) {
      getLessonOrders()
        .then((data) => {
          if (Array.isArray(data)) {
            const pending = data.filter(
              (o) => o.status === "pending" || o.status === "Pending",
            );
            setWorkRequests(
              pending.map((o) => ({
                id: o._id ?? o.id,
                client: o.student_name ?? "Student",
                service: o.lesson_title ?? config.serviceLabel ?? "Lesson",
                location: sdCommon("online"),
                amount: o.amount ? `${$m(parseFloat(o.amount))}` : "—",
                scheduled: o.scheduled_at ?? "ASAP",
              })),
            );
          }
        })
        .catch(() => { });
    } else if (useAppointments) {
      getAppointments()
        .then((data) => {
          if (Array.isArray(data)) {
            const pending = data.filter(
              (o) => o.status === "pending" || o.status === "Pending",
            );
            setWorkRequests(
              pending.map((o) => ({
                id: o._id ?? o.id,
                client: o.patient_name ?? o.user_name ?? "Patient",
                service:
                  o.appointment_type ??
                  o.specialty ??
                  config.serviceLabel ??
                  "Appointment",
                location: o.mode === "online" ? sdCommon("online") : sdCommon("inPerson"),
                amount: o.amount
                  ? `${$m(parseFloat(o.amount))}`
                  : "Free",
                scheduled: o.scheduled_at ?? o.appointment_date ?? "ASAP",
              })),
            );
          }
        })
        .catch(() => { });
    }
    if (!useLessonOrders && !useAppointments) {
      getServiceOrders()
        .then((data) => {
          if (Array.isArray(data)) {
            const mapped = data.map((o) => ({
              id: `#SV-${o.order_id ?? o.id}`,
              _id: o.order_id ?? o.id,
              client: o.client_name ?? o.user_name ?? "Client",
              service: o.service_name ?? config.serviceLabel ?? "Service",
              amount: o.amount
                ? `${$m((parseFloat(o.amount) * 0.79))}`
                : "—",
              status: o.status
                ? o.status.charAt(0).toUpperCase() + o.status.slice(1)
                : "Pending",
            }));
            setSvcOrders(mapped);
            const rev = data.reduce(
              (s, o) => s + parseFloat(o.amount || 0) * 0.79,
              0,
            );
            const active = data.filter((o) =>
              ["active", "in progress", "started"].includes(
                (o.status || "").toLowerCase(),
              ),
            ).length;
            setSvcStats({
              total: data.length,
              active,
              orderCount: data.length,
              revenue: rev,
            });
          }
        })
        .catch(() => { });
    }
    return () => s.off(eventName, handler);
  }, []);

  async function handleAcceptOrder(req) {
    setOrderLoading((p) => ({ ...p, [req.id]: true }));
    try {
      if (req.isMedicalBooking || isDoctorsPortal) {
        await acceptEngineBooking(req.id);
        await reloadMedBookings();
      } else if (useLessonOrders) await acceptLessonOrder(req.id);
      else if (useAppointments) await confirmAppointment(req.id);
      else await acceptServiceOrder(req.id);
      if (!isDoctorsPortal) {
        setActiveOrder({ ...req, status: "accepted" });
        setWorkRequests((prev) => prev.filter((r) => r.id !== req.id));
      }
    } catch { /* accept failed */ }
    setOrderLoading((p) => ({ ...p, [req.id]: false }));
  }

  async function handleDeclineOrder(req) {
    setOrderLoading((p) => ({ ...p, [req.id]: true }));
    try {
      if (req.isMedicalBooking || isDoctorsPortal) {
        await declineEngineBooking(req.id);
        await reloadMedBookings();
      } else if (useLessonOrders) await declineLessonOrder(req.id);
      else if (useAppointments) await declineAppointment(req.id);
      else await declineServiceOrder(req.id);
      setWorkRequests((prev) => prev.filter((r) => r.id !== req.id));
    } catch { /* decline failed */ }
    setOrderLoading((p) => ({ ...p, [req.id]: false }));
  }

  async function handleMedicalCheckIn(req) {
    setOrderLoading((p) => ({ ...p, [req.id]: true }));
    try {
      await checkInEngineBooking(req.id);
      await reloadMedBookings();
    } catch { /* check-in failed */ }
    setOrderLoading((p) => ({ ...p, [req.id]: false }));
  }

  async function handleMedicalComplete(req) {
    setOrderLoading((p) => ({ ...p, [req.id]: true }));
    try {
      await completeEngineBooking(req.id);
      await reloadMedBookings();
    } catch { /* complete failed */ }
    setOrderLoading((p) => ({ ...p, [req.id]: false }));
  }

  async function handleArrivedOrder() {
    if (!activeOrder) return;
    try {
      await arrivedServiceOrder(activeOrder.id);
      setActiveOrder((p) => ({ ...p, status: "arrived" }));
    } catch { /* arrive failed */ }
  }

  async function handleStartOrder() {
    if (!activeOrder) return;
    try {
      useLessonOrders
        ? await startLesson(activeOrder.id)
        : await startServiceOrder(activeOrder.id);
      setActiveOrder((p) => ({ ...p, status: "started" }));
    } catch { /* start failed */ }
  }

  async function handleCompleteOrder() {
    if (!activeOrder) return;
    try {
      useLessonOrders
        ? await completeLesson(activeOrder.id)
        : await completeServiceOrder(activeOrder.id);
      const completed = {
        ...activeOrder,
        status: "Completed",
        created_at: new Date().toISOString(),
      };
      setSvcOrders((prev) =>
        prev.some((o) => o._id === activeOrder._id || o.id === activeOrder.id)
          ? prev.map((o) =>
            o._id === activeOrder._id || o.id === activeOrder.id
              ? { ...o, status: "Completed" }
              : o,
          )
          : [completed, ...prev],
      );
      setSvcStats((prev) => {
        const amountNum =
          parseFloat((activeOrder.amount || "0").replace(/[^0-9.]/g, "")) /
          0.79;
        return {
          ...prev,
          active: Math.max(0, prev.active - 1),
          revenue: prev.revenue + amountNum * 0.79,
        };
      });
      setActiveOrder(null);
      window.dispatchEvent(new Event("wallet-balance-updated"));
    } catch { /* complete failed */ }
  }

  async function handleAddService() {
    if (!serviceForm.name.trim()) {
      setServiceFormMsg(sdCommon("serviceNameRequired"));
      return;
    }
    setServiceFormLoading(true);
    setServiceFormMsg("");
    try {
      const u = getUser();
      const typeId = serviceForm.service_type_id
        ? parseInt(serviceForm.service_type_id)
        : null;
      const catId = serviceForm.service_category_id
        ? parseInt(serviceForm.service_category_id)
        : null;
      const selectedType = svcTypes.find((t) => t.service_type_id === typeId);
      const selectedCat = svcCategories.find(
        (c) => c.service_category_id === catId,
      );
      await createServiceListing({
        service_name: serviceForm.name,
        description: serviceForm.description,
        category:
          selectedCat?.service_category_name ??
          selectedType?.service_type_name ??
          "General",
        service_type_id: typeId,
        service_category_id: catId,
        provider_id: u?.user_id ?? u?.id,
        ...(serviceForm.amount ? { amount: parseFloat(serviceForm.amount) } : {}),
      });
      setServices((prev) => [
        { name: serviceForm.name, orders: 0, status: "Active" },
        ...prev,
      ]);
      setServiceForm({
        name: "",
        description: "",
        service_type_id: "",
        service_category_id: "",
      });
      setShowAddServiceModal(false);
    } catch (err) {
      setServiceFormMsg(
        err?.response?.data?.error ??
        err?.message ??
        sdCommon("failedSaveService"),
      );
    }
    setServiceFormLoading(false);
  }

  // --- Freelancer Order Handlers ---

  async function handleFreelancerOrderStatus(order, newStatus) {
    const confirmMsg = newStatus === "IN_PROGRESS"
      ? "Are you sure you want to mark this order as IN PROGRESS? This will notify the buyer that you have started working on their order."
      : "Are you sure you want to mark this order as DELIVERED? This action is irreversible and will notify the buyer that their order is ready for review.";

    const confirmed = await confirmOrderAction({
      title: "Update Order Status",
      message: confirmMsg,
      confirmLabel: newStatus === "IN_PROGRESS" ? "Start Working" : "Mark as Delivered",
      danger: newStatus === "DELIVERED",
    });

    if (!confirmed) return;

    setOrderLoading((p) => ({ ...p, [order.id]: true }));
    try {
      const res = await updateFreelanceOrderStatus(order.id, newStatus);
      if (res.successful) {
        setFreelancerOrders((prev) =>
          prev.map((o) =>
            o.id === order.id
              ? { ...o, status: res.data.status, is_completed: res.data.is_completed, completed_at: res.data.completed_at }
              : o
          )
        );
      }
    } catch (err) {
      console.error("Failed to update order status:", err);
    } finally {
      setOrderLoading((p) => ({ ...p, [order.id]: false }));
    }
  }

  // --- Freelancer Profile Update ---

  const handleUpdateFreelancerProfile = async (vals) => {
    const payload = {};

    // Check each field for changes - use strict comparison
    if (vals.display_name !== undefined && vals.display_name !== freelancerProfile?.display_name) {
      payload.display_name = vals.display_name;
    }
    if (vals.freelance_bio !== undefined && vals.freelance_bio !== freelancerProfile?.freelance_bio) {
      payload.freelance_bio = vals.freelance_bio;
    }
    if (vals.tagline !== undefined && vals.tagline !== freelancerProfile?.tagline) {
      payload.tagline = vals.tagline;
    }
    if (vals.country !== undefined && vals.country !== freelancerProfile?.country) {
      payload.country = vals.country;
    }
    if (vals.city !== undefined && vals.city !== freelancerProfile?.city) {
      payload.city = vals.city;
    }

    // Handle languages - ensure we have arrays and compare properly
    if (vals.languages !== undefined) {
      const currentLanguages = freelancerProfile?.languages || [];
      const newLanguages = Array.isArray(vals.languages) ? vals.languages : vals.languages.split(',').map(s => s.trim()).filter(Boolean);

      // Sort both arrays for consistent comparison
      const sortedCurrent = [...currentLanguages].sort();
      const sortedNew = [...newLanguages].sort();

      if (JSON.stringify(sortedCurrent) !== JSON.stringify(sortedNew)) {
        payload.languages = newLanguages;
      }
    }

    // Handle skills - ensure we have arrays and compare properly
    if (vals.skills !== undefined) {
      const currentSkills = freelancerProfile?.skills || [];
      const newSkills = Array.isArray(vals.skills) ? vals.skills : vals.skills.split(',').map(s => s.trim()).filter(Boolean);

      // Sort both arrays for consistent comparison
      const sortedCurrent = [...currentSkills].sort();
      const sortedNew = [...newSkills].sort();

      if (JSON.stringify(sortedCurrent) !== JSON.stringify(sortedNew)) {
        payload.skills = newSkills;
      }
    }

    // Set loading state
    setProfileSaveLoading(true);
    setProfileSaveError(null);
    setProfileSaveSuccess(false);

    try {
      const res = await updateFreelancerProfile({
        display_name: freelancerProfile?.display_name,
        freelance_bio: freelancerProfile?.freelance_bio,
        tagline: freelancerProfile?.tagline,
        country: freelancerProfile?.country,
        city: freelancerProfile?.city,
        languages: freelancerProfile?.languages,
        skills: freelancerProfile?.skills
      });
      if (res.successful) {
        // Update the state with the response data
        setFreelancerProfile(res.data);
        setProfileSaveSuccess(true);
        setTimeout(() => setProfileSaveSuccess(false), 3000);
      } else {
        setProfileSaveError(res.message || "Failed to update profile");
        setTimeout(() => setProfileSaveError(null), 3000);
      }
    } catch (err) {
      console.error("Failed to update profile:", err);
      setProfileSaveError(err?.response?.data?.message || "Failed to update profile");
      setTimeout(() => setProfileSaveError(null), 3000);
    } finally {
      setProfileSaveLoading(false);
    }
  };

