                        color: '#fff',
                        fontSize: 11,
                        fontWeight: 700,
                        fontFamily: "'DM Sans', sans-serif",
                        backdropFilter: "blur(8px)",
                        boxShadow: "0 2px 12px var(--color-shadow)",
